/// The capabilities (`shared/protocol/capabilities.json`, ARCHITECTURE.md §8.3): optional
/// features named by string, announced at join (`dwell_protocol::capabilities`).
pub mod capability_names {
    pub const MAX_NAMES: usize = 64;
    pub const MAX_NAME_BYTES: usize = 48;
    /// A saved structure's placement goes as its own region-edit op (RegionEditOp::Structure, the Paste body), which the server refuses where the world's mode lacks the `structures` ability (shared/modes/modes.json; STRUCTURES.md §9). Without it a client sends plain pastes.
    pub const STRUCTURES_PLACE: &str = "structures.place";
    /// The player's grid travels on the wire (docs/proposals/MOON_WORLD.md §7.2): a snapshot ends with the local player's grid (its index in shared/worldgen/grids.json, 0 the home grid) and, off home, the grid's frame (origin, rotation); the other grids' chunks arrive as ChunkData and ChunkUnload ending with their grid byte. Without it the server sends neither, and a player off home is seen at their world position.
    pub const GRID_FRAMES: &str = "grid.frames";
    /// A Damage message's cells end with each hit mark's chunk (docs/BLOCK_DAMAGE.md §9: how big a piece the hit took off, in sixteenths of the block's mark; a metal tool's 32, owner 2026-11-12 "Metal tools break double sized bigger chunks off"). Without it the server sends none and the client draws every mark at ×1.
    pub const DAMAGE_CHUNKS: &str = "damage.chunks";
    /// A Creatures message ends with its NPCs' part (WORK_QUEUE item 38, CHARACTERS.md §11.11): per NPC its id, kind name, idle pose (stand, look, sit) and palette variant seed, from which the client picks the NPC's colours by shared/creatures/creatures.json. Without it the server leaves the part out, and an NPC is drawn as its model's plain creature.
    pub const CREATURES_NPCS: &str = "creatures.npcs";
    /// Swordplay on the wire (WORK_QUEUE item 35, round 2): the server sends `Swordplay` (each strike's outcome, blocked / glanced / connected, where, and both stances, to clients within the weapon's `clash.hearM`; and who holds a raised guard in which stance, players and NPCs), and the client says its raised block with `ChopAction::Guard`. Without it neither is sent: an older client sees no clash and no raised swords, and an older server is never sent a guard.
    pub const WEAPONS_CLASH: &str = "weapons.clash";
    /// A Creatures message ends, after its NPCs' part (written empty if need be), with the animals' idle poses (WORK_QUEUE item 39): per creature its id and pose (stand, graze, lookUp, earFlick, sit, lie; the ecology's idle poses), drawn as the model's `poses` data (shared/models/models.json) blended over its idle clip. Without it the server leaves the part out and the animals play their idle clip.
    pub const CREATURES_POSES: &str = "creatures.poses";
    /// An NPC's pose in a Creatures message's NPCs' part may be 3 or 4 (`NPC_STRIKE_POSES`: striking level, striking vertical) while it swings its sword (WORK_QUEUE item 35), and the client plays that swing's clip. Without it the server sends its idle pose instead, as older clients read it.
    pub const NPCS_SWINGS: &str = "npcs.swings";
    /// The client sends `TheaterViewpoint` (docs/THEATER_MODE.md §7, T-4): theater mode's camera position while a camera path plays (at most world.theaterViewpointHz a second), and an empty one when it ends. The server adds it to the player's interest (chunks streamed around it, creatures and NPCs spawned and simulated near it, the near ecology and the water stepped there) only where the world's mode has the `theaterViewpoint` ability (shared/modes/modes.json: creative), within world.theaterViewpointMaxM of the body; elsewhere it ignores it. Without it the client never sends one.
    pub const THEATER_VIEWPOINT: &str = "theater.viewpoint";
    /// A breaking tool's hit (one with a `contactS`, shared/tools/tools.json; docs/BLOCK_DAMAGE.md §11) is sent at its swing's contact, aimed at what the crosshair targets then, and the server lands it on arrival (reach, line of sight and the edit rate checked from the eye at that tick) instead of `contactS` after it arrives. Without it (either side) the client sends the hit at the click, at the cell clicked, and the server lands it `contactS` after it arrives.
    pub const HITS_AT_CONTACT: &str = "hits.at_contact";
    /// Every capability this build knows, in the table's order.
    pub const ALL: &[&str] = &[STRUCTURES_PLACE, GRID_FRAMES, DAMAGE_CHUNKS, CREATURES_NPCS, WEAPONS_CLASH, CREATURES_POSES, NPCS_SWINGS, THEATER_VIEWPOINT, HITS_AT_CONTACT];
}
